// dayjs-style date helper (format / add / subtract / startOf / diff). Own code, GPL-3.0 — not the dayjs package.
const UNIT = { ms: 1, millisecond: 1, s: 1e3, second: 1e3, m: 6e4, minute: 6e4, h: 36e5, hour: 36e5, d: 864e5, day: 864e5, w: 6048e5, week: 6048e5 };
const norm = u => { const s = String(u || 'ms'); return s.length > 2 ? s.replace(/s$/, '') : s; };
const two = n => (n < 10 ? '0' : '') + n;

function parse(v) {
  if (v === undefined || v === null) return new Date();
  if (v instanceof Day) return new Date(v.valueOf());
  if (typeof v === 'string' && !/[zZ]$|[+-]\d\d:?\d\d$/.test(v)) {
    const m = /^(\d{4})[-/]?(\d{1,2})?[-/]?(\d{0,2})[Tt\s]*(\d{1,2})?:?(\d{1,2})?:?(\d{1,2})?/.exec(v);
    if (m) return new Date(+m[1], (m[2] || 1) - 1, +(m[3] || 1), +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
  }
  return new Date(v);
}

class Day {
  constructor(v) { this.$d = parse(v); }
  valueOf() { return this.$d.getTime(); }
  unix() { return Math.floor(this.valueOf() / 1000); }
  toDate() { return new Date(this.valueOf()); }
  toISOString() { return this.$d.toISOString(); }
  toString() { return this.$d.toUTCString(); }
  isValid() { return !isNaN(this.valueOf()); }
  year() { return this.$d.getFullYear(); }
  month() { return this.$d.getMonth(); }
  date() { return this.$d.getDate(); }
  day() { return this.$d.getDay(); }
  hour() { return this.$d.getHours(); }
  minute() { return this.$d.getMinutes(); }
  second() { return this.$d.getSeconds(); }
  add(n, u) {
    const k = norm(u), d = new Date(this.valueOf());
    if (k === 'month' || k === 'M') d.setMonth(d.getMonth() + Number(n));
    else if (k === 'year' || k === 'y') d.setFullYear(d.getFullYear() + Number(n));
    else d.setTime(d.getTime() + Number(n) * (UNIT[k] || 1));
    return new Day(d);
  }
  subtract(n, u) { return this.add(-n, u); }
  startOf(u) {
    const d = this.$d, k = norm(u), year = k === 'year' || k === 'y', month = k === 'month' || k === 'M', hour = k === 'hour' || k === 'h', minute = k === 'minute' || k === 'm';
    return new Day(new Date(d.getFullYear(), year ? 0 : d.getMonth(), year || month ? 1 : d.getDate(), hour || minute ? d.getHours() : 0, minute ? d.getMinutes() : 0));
  }
  endOf(u) { return this.startOf(u).add(1, u).subtract(1, 'ms'); }
  diff(o, u) { return Math.trunc((this.valueOf() - new Day(o).valueOf()) / (UNIT[norm(u)] || 1)); }
  isBefore(o) { return this.valueOf() < new Day(o).valueOf(); }
  isAfter(o) { return this.valueOf() > new Day(o).valueOf(); }
  isSame(o, u) { return u ? this.startOf(u).valueOf() === new Day(o).startOf(u).valueOf() : this.valueOf() === new Day(o).valueOf(); }
  format(f) {
    const d = this.$d, h12 = d.getHours() % 12 || 12;
    const map = {
      YYYY: d.getFullYear(), YY: String(d.getFullYear()).slice(-2), MM: two(d.getMonth() + 1), M: d.getMonth() + 1, DD: two(d.getDate()), D: d.getDate(),
      HH: two(d.getHours()), H: d.getHours(), hh: two(h12), h: h12, mm: two(d.getMinutes()), m: d.getMinutes(), ss: two(d.getSeconds()), s: d.getSeconds(),
      SSS: String(1000 + d.getMilliseconds()).slice(1), A: d.getHours() < 12 ? 'AM' : 'PM', a: d.getHours() < 12 ? 'am' : 'pm', d: d.getDay(),
    };
    return (f || 'YYYY-MM-DDTHH:mm:ss').replace(/\[([^\]]*)\]|YYYY|YY|MM|M|DD|D|HH|H|hh|h|mm|m|SSS|ss|s|A|a|d/g, (m, lit) => (lit !== undefined ? lit : map[m]));
  }
}

export function dayjs(v) { return new Day(v); }
dayjs.unix = n => new Day(n * 1000);
dayjs.extend = () => dayjs;
dayjs.locale = () => 'zh-cn';
export default dayjs;
